import json
import re
import logging
from itertools import islice

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtiEventReader(object):

    def __init__(self, file_obj, **kwargs):
        super(TtiEventReader, self).__init__(**kwargs)
        self._file_obj = file_obj
        self._replacements = {
            re.compile(k, re.IGNORECASE): v
            for k, v in (
                (br"-?\bnan\b", b"NaN"),
                (br"\binf\b", b"Infinity"),
                (br"-\binf\b", b"-Infinity"))}

    def __iter__(self):
        event = []
        inside_event = False

        for line in islice(self._file_obj, 2, None):
            if line.startswith(b"{\n"):
                inside_event = True
            if inside_event:
                if line.startswith(b"}"):
                    event.append(b"}")
                    inside_event = False
                    yield self._yield_event_or_log_warning(event)
                    event = []
                else:
                    event.append(line)
            if line == b'':
                break

    def _yield_event_or_log_warning(self, event):
        event_string = b''.join(event)

        event_valid_json = event_string
        for regex, substitution in self._replacements.items():
            event_valid_json = regex.sub(substitution, event_valid_json)
        try:
            event_dict = json.loads(event_valid_json.decode('utf-8'))
            return self._get_tti_event(event_dict)
        except ValueError as err:
            logger.warning(err)
            logger.warning(event_string.decode('utf-8'))

    def _get_tti_event(self, d):
        return d
